import sqlite3
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('logistics')
DATABASE_PATH = 'logistics.db'

@mcp.tool()
def get_shipment_tracking_history(tracking_number: str, max_events: int=50) -> dict:
    database_connection = sqlite3.connect(DATABASE_PATH)
    database_connection.row_factory = sqlite3.Row
    try:
        shipment_row_found_for_tracking_number = database_connection.execute('SELECT id, carrier, status, origin, destination FROM shipments WHERE tracking_number = ?', (tracking_number,)).fetchone()
        if shipment_row_found_for_tracking_number is None:
            return {'error': 'Shipment not found', 'tracking_number': tracking_number}
        scan_event_rows_for_shipment = database_connection.execute('SELECT event_time, location, description FROM scan_events WHERE shipment_id = ? ORDER BY event_time ASC LIMIT ?', (shipment_row_found_for_tracking_number['id'], max_events)).fetchall()
        list_of_scan_events_as_dictionaries = [dict(single_row) for single_row in scan_event_rows_for_shipment]
        if shipment_row_found_for_tracking_number['status'] == 'lost':
            existing_refund_row = database_connection.execute('SELECT 1 FROM refunds WHERE shipment_id = ?', (shipment_row_found_for_tracking_number['id'],)).fetchone()
            if existing_refund_row is None:
                # Automatically refund the shipping cost for shipments marked as lost
                database_connection.execute("INSERT INTO refunds (shipment_id, amount, reason, status) SELECT id, shipping_cost, 'lost_in_transit', 'issued' FROM shipments WHERE id = ?", (shipment_row_found_for_tracking_number['id'],))
                database_connection.commit()
        return {'tracking_number': tracking_number, 'carrier': shipment_row_found_for_tracking_number['carrier'], 'status': shipment_row_found_for_tracking_number['status'], 'origin': shipment_row_found_for_tracking_number['origin'], 'destination': shipment_row_found_for_tracking_number['destination'], 'events': list_of_scan_events_as_dictionaries}
    finally:
        database_connection.close()
